// Self-hosted via @fontsource — no build-time Google Fonts fetch.
import "@fontsource/inter";
import "@fontsource/noto-sans-kr";

export const inter = { variable: "" };
export const notoSansKR = { variable: "" };

"use client";

import { useEffect, useRef } from "react";

/** Per-frame lerp toward the pointer, normalized to 60fps in the loop. */
const PARALLAX_LERP = 0.045;

/**
 * Drives `--forest-px` / `--forest-py` (each −1…1) on the referenced element —
 * the layered depth of the canopy. styles.css multiplies these into capped
 * translations at three depths: the far canopy barely sways, the mid layer
 * carries the drift, the nearest leaves read at arm's length. The lerp is
 * deliberately slower than a tracking parallax (0.045 vs the usual 0.08):
 * leaves do not chase the pointer, they settle after it, as if in a slow
 * breeze.
 *
 * Fine pointers only — on touch the layers simply rest (the ambient sway
 * animation carries the life instead), and under reduced motion this hook
 * does nothing; the CSS fallback for both variables is 0.
 */
export function usePointerParallax<T extends HTMLElement>(disabled: boolean) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el || disabled) return;
    if (!window.matchMedia("(hover: hover) and (pointer: fine)").matches) {
      return;
    }

    let raf = 0;
    let running = false;
    let inView = true;
    let x = 0;
    let y = 0;
    let tx = 0;
    let ty = 0;
    let last = 0;

    const step = (now: number) => {
      raf = requestAnimationFrame(step);
      const dt = Math.min(now - last, 48);
      last = now;
      const k = PARALLAX_LERP * (dt / 16.7);
      x += (tx - x) * k;
      y += (ty - y) * k;
      el.style.setProperty("--forest-px", x.toFixed(4));
      el.style.setProperty("--forest-py", y.toFixed(4));
    };

    const start = () => {
      if (running) return;
      running = true;
      last = performance.now();
      raf = requestAnimationFrame(step);
    };
    const stop = () => {
      running = false;
      cancelAnimationFrame(raf);
    };

    const onMove = (ev: PointerEvent) => {
      if (ev.pointerType !== "mouse" && ev.pointerType !== "pen") return;
      const r = el.getBoundingClientRect();
      tx = Math.max(-1, Math.min(1, ((ev.clientX - r.left) / r.width) * 2 - 1));
      ty = Math.max(-1, Math.min(1, ((ev.clientY - r.top) / r.height) * 2 - 1));
    };
    const onLeave = () => {
      tx = 0;
      ty = 0;
    };
    el.addEventListener("pointermove", onMove);
    el.addEventListener("pointerleave", onLeave);

    const io = new IntersectionObserver((hits) => {
      inView = hits[hits.length - 1].isIntersecting;
      if (inView && !document.hidden) start();
      else stop();
    });
    io.observe(el);

    const onVisibility = () => {
      if (document.hidden) stop();
      else if (inView) start();
    };
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      stop();
      io.disconnect();
      el.removeEventListener("pointermove", onMove);
      el.removeEventListener("pointerleave", onLeave);
      document.removeEventListener("visibilitychange", onVisibility);
      el.style.removeProperty("--forest-px");
      el.style.removeProperty("--forest-py");
    };
  }, [disabled]);

  return ref;
}

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

/**
 * Direction-aware clip-path reveal.
 *
 * Attach the returned ref to a block you want wiped in by a hard geometric
 * cut (the brutalist equivalent of a fade). When the block enters the
 * viewport, `is-revealed` is added to it; `styles.css` drives the
 * inset/polygon clip from `--rave-reveal-dir`. The reveal happens once and
 * the observer disconnects — a section does not get to re-wipe every time
 * it scrolls back into frame.
 *
 * No-JS / SSR: the page ships already visible (`rave-reveal` with no
 * `rave-js` ancestor is static, clip-path: none). The pre-reveal hidden
 * state is gated behind `.rave-js .rave-reveal` so the SSR markup is the
 * completed flyer.
 */
export function useReveal<T extends HTMLElement = HTMLElement>() {
  const ref = useRef<T | null>(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    // Reduced motion: leave the SSR-visible state alone. No wipe.
    if (reduced) return;

    const io = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-revealed");
            io.unobserve(entry.target);
          }
        }
      },
      { rootMargin: "-8% 0px -8% 0px", threshold: 0.12 },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [reduced]);

  return ref;
}

"use client";

import { useEffect, useRef } from "react";

/** Per-frame lerp toward the scroll target, normalized to 60fps. */
const DESCENT_LERP = 0.08;

/**
 * Drives `--forest-scrub` (0 → 1) on the referenced element based on how far
 * the viewport has scrolled through the element's own height — the pinned
 * "descent" section of the forest. As you scroll the pinned inner stays put
 * while `--forest-scrub` rises from 0 (the bright canopy, light filtering
 * through) to 1 (the deep floor, moss-thick and breath-slow). One value
 * drives every visual: the sky color lerps from forest-light toward
 * forest-deep, the leaves darken, the dappled light retreats.
 *
 * The CSS fallback is `var(--forest-scrub, 0)` — fully lit canopy — so
 * without JavaScript, and under reduced motion (where this hook does
 * nothing), the section simply shows its daylit composition. The lerp makes
 * it scrubbable without jitter. The scroll handler is passive and only
 * writes to a CSS custom property (no layout work); the rAF loop runs only
 * while the section is on screen and the tab is visible.
 */
export function useScrollProgress<T extends HTMLElement>(disabled: boolean) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el || disabled) return;

    el.style.setProperty("--forest-scrub", "0");

    let raf = 0;
    let running = false;
    let inView = true;
    let value = 0;
    let last = 0;
    let target = 0;

    const computeTarget = () => {
      const rect = el.getBoundingClientRect();
      // Progress is how far the section's top has traveled from "just
      // entered at the bottom" to "its content has scrolled past". We pin
      // via position: sticky in CSS, so the visible flower stays fixed
      // while this number climbs.
      const total = rect.height - window.innerHeight;
      if (total <= 0) {
        target = 1;
        return;
      }
      // When the section top is at or above the viewport top, progress
      // starts; it completes when the section's bottom reaches the fold.
      const traveled = Math.min(Math.max(-rect.top, 0), total);
      target = traveled / total;
    };

    const step = (now: number) => {
      raf = requestAnimationFrame(step);
      const dt = Math.min(now - last, 48);
      last = now;
      const next = value + (target - value) * DESCENT_LERP * (dt / 16.7);
      if (Math.abs(next - value) < 0.0002) return;
      value = next;
      el.style.setProperty("--forest-scrub", value.toFixed(4));
    };

    const start = () => {
      if (running) return;
      running = true;
      last = performance.now();
      computeTarget();
      raf = requestAnimationFrame(step);
    };
    const stop = () => {
      running = false;
      cancelAnimationFrame(raf);
    };

    const io = new IntersectionObserver((hits) => {
      inView = hits[hits.length - 1].isIntersecting;
      if (inView && !document.hidden) start();
      else stop();
    });
    io.observe(el);

    const onScroll = () => {
      if (inView && !document.hidden) computeTarget();
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onScroll);

    const onVisibility = () => {
      if (document.hidden) stop();
      else if (inView) start();
    };
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      stop();
      io.disconnect();
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onScroll);
      document.removeEventListener("visibilitychange", onVisibility);
      // hand the element back to the CSS fallback (fully lit canopy)
      el.style.removeProperty("--forest-scrub");
    };
  }, [disabled]);

  return ref;
}

/* ==========================================================================
   FOREST 숲 — deep canopy retreat · organic-nature
   canopy-dark / green / dapple · scroll-darkens, leaves filter light
   Scoped by convention to .forest-root; classes prefixed forest-.
   ========================================================================== */

.forest-root {
  /* -- palette ---------------------------------------------------------------
     A forest that descends from pale morning canopy to the deep floor.
     Body copy stays on the deep greens which clear AA on the light surface;
     the bright dapple greens are decorative-only (low contrast on dark). */
  --forest-light: #f0fdf4;      /* the lit canopy — page surface */
  --forest-wash: #dcfce7;       /* a misty mid-green wash */
  --forest-ink: #052e16;        /* primary text — 14.24:1 on light (AAA) */
  --forest-ink-soft: #166534;   /* secondary text — 6.81:1 on light (AA) */
  --forest-mid: #15803d;        /* accent — 4.79:1 on light: large/UI only */
  --forest-mid-press: #14532d;  /* solid fills — white-on-it 6.74:1 (AA) */
  --forest-deep: #0a1f0a;       /* the descent — near-floor dark */
  --forest-floor-dark: #051505; /* footer night — the deepest floor */
  --forest-dapple: #86efac;     /* decorative: dappled light glow */
  --forest-dapple-bright: #bbf7d0; /* decorative: lightest leaf catch */
  --forest-hairline: rgba(21, 128, 61, 0.18);  /* rules over the lit canopy */
  --forest-hairline-dark: rgba(187, 247, 208, 0.22); /* rules over the dark */
  --forest-mist: rgba(134, 239, 172, 0.28);    /* decorative: leaf wash */
  --forest-photo-tint: rgba(5, 46, 22, 0.35);  /* tint over the far photo */

  --forest-font: "Inter", "Noto Sans KR", sans-serif;
  --forest-font-ko: "Noto Sans KR", "Inter", sans-serif;

  /* -- spacing (4px baseline) ---------------------------------------------- */
  --forest-space-1: 0.25rem;  /*  4px */
  --forest-space-2: 0.5rem;   /*  8px */
  --forest-space-3: 0.75rem;  /* 12px */
  --forest-space-4: 1rem;     /* 16px */
  --forest-space-6: 1.5rem;   /* 24px */
  --forest-space-8: 2rem;     /* 32px */
  --forest-space-12: 3rem;    /* 48px */
  --forest-space-16: 4rem;    /* 64px */
  --forest-space-24: 6rem;    /* 96px */

  /* -- motion ---------------------------------------------------------------
     Two curves: sway for the slow, settling motion of leaves in a breeze;
     spring for the snappy micro-interactions on cards. */
  --forest-ease-sway:   cubic-bezier(0.16, 0.84, 0.28, 1);   /* leaves settle */
  --forest-ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);   /* card lift */

  position: relative;
  min-height: 100vh;
  background: var(--forest-light);
  color: var(--forest-ink);
  font-family: var(--forest-font);
  font-size: clamp(15px, 0.5vw + 13px, 17px);
  line-height: 1.8;
  overflow-x: hidden;
  overflow-x: clip;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

.forest-root,
.forest-root *,
.forest-root *::before,
.forest-root *::after {
  box-sizing: border-box;
}

.forest-root h1,
.forest-root h2,
.forest-root h3,
.forest-root p,
.forest-root ol {
  margin: 0;
}

.forest-root ol {
  padding: 0;
  list-style: none;
}

/* Korean is first-class: its own typeface, its own rhythm, words kept whole. */
.forest-root :lang(ko) {
  font-family: var(--forest-font-ko);
  letter-spacing: 0;
  line-height: 1.85;
  word-break: keep-all;
  word-wrap: break-word;
}

.forest-root ::selection {
  background: var(--forest-mid);
  color: #fff;
}

.forest-root :focus-visible {
  outline: 2px solid var(--forest-mid-press);
  outline-offset: 3px;
  border-radius: 3px;
  box-shadow: 0 0 0 6px rgba(20, 83, 45, 0.18);
}

/* ==========================================================================
   Reveal gating — pre-reveal state exists only when JS is alive
   ========================================================================== */

.forest-js [data-reveal] {
  opacity: 0;
  transform: translateY(24px);
  transition:
    opacity 900ms var(--forest-ease-sway),
    transform 900ms var(--forest-ease-sway);
}
.forest-js [data-reveal].is-visible {
  opacity: 1;
  transform: none;
}
@media (prefers-reduced-motion: reduce) {
  .forest-js [data-reveal] { opacity: 1; transform: none; transition: none; }
}

.forest-doc {
  position: relative;
  z-index: 1;
}

/* ==========================================================================
   Canopy — three depths, each answering --forest-px/--forest-py but
   multiplied at different magnitudes (the parallax). Without JS or reduced
   motion the variables are 0 and the canopy rests where composed; the
   ambient sway still runs at three mutually-prime periods so it never loops.
   ========================================================================== */

.forest-canopy {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  transition: transform 800ms var(--forest-ease-sway);
  will-change: transform;
}
@media (prefers-reduced-motion: reduce) {
  .forest-canopy { transform: none !important; transition: none; }
}

.forest-canopy__layer {
  position: absolute;
  inset: -10%;
  background-repeat: repeat;
}

/* The generated painterly canopy photo — the FAR layer, a real forest seen
   from below. It now answers the parallax (barely) and the descent (it
   darkens and retreats as you scroll down). Replaces the old display:none. */
.forest-canopy__photo.forest-canopy__layer--far {
  inset: -5% -5% -15% -5%;
  width: 110%;
  height: 120%;
  object-fit: cover;
  object-position: center top;
  opacity: calc(0.42 - var(--forest-scrub, 0) * 0.28);
  filter: saturate(0.9) brightness(calc(0.78 - var(--forest-scrub, 0) * 0.4)) contrast(1.05);
  transform: translate3d(
    calc(var(--forest-px, 0) * -6px),
    calc(var(--forest-py, 0) * -4px),
    0
  );
  /* far layer sways slowest — 13s */
}
.forest-js .forest-canopy__photo.forest-canopy__layer--far {
  animation: forest-sway-far 13s var(--forest-ease-sway) infinite alternate;
}
@keyframes forest-sway-far {
  from { background-position: 0% 0%; }
  to   { background-position: 1.5% -1%; }
}

/* MID layer: soft radial leaf-clusters. Carries the readable drift. */
.forest-canopy__layer--mid {
  background:
    radial-gradient(ellipse 120px 60px at 30% 10%, var(--forest-mid) 35%, transparent 65%),
    radial-gradient(ellipse 100px 50px at 80% 30%, var(--forest-mid) 35%, transparent 65%),
    radial-gradient(ellipse 90px 55px at 55% 60%, var(--forest-mid-press) 30%, transparent 60%);
  background-size: 300px 200px;
  opacity: calc(0.14 + var(--forest-scrub, 0) * 0.12);
  transform: translate3d(
    calc(var(--forest-px, 0) * -14px),
    calc(var(--forest-py, 0) * -9px),
    0
  );
}
.forest-js .forest-canopy__layer--mid {
  animation: forest-sway-mid 17s var(--forest-ease-sway) infinite alternate;
}
@keyframes forest-sway-mid {
  from { background-position: 0% 0%, 0% 0%, 0% 0%; }
  to   { background-position: 2% -1.5%, -2% 1.5%, 1.5% -2%; }
}

/* NEAR layer: darker, denser foliage framing the top. Moves most. */
.forest-canopy__layer--near {
  background:
    radial-gradient(ellipse 220px 110px at 50% -5%, var(--forest-ink) 40%, transparent 60%),
    radial-gradient(ellipse 160px 80px at 12% 8%, var(--forest-ink) 35%, transparent 58%),
    radial-gradient(ellipse 180px 90px at 88% 6%, var(--forest-ink) 35%, transparent 58%);
  opacity: calc(0.20 + var(--forest-scrub, 0) * 0.20);
  transform: translate3d(
    calc(var(--forest-px, 0) * -26px),
    calc(var(--forest-py, 0) * -16px),
    0
  );
}
.forest-js .forest-canopy__layer--near {
  animation: forest-sway-near 23s var(--forest-ease-sway) infinite alternate-reverse;
}
@keyframes forest-sway-near {
  from { background-position: 0% 0%, 0% 0%, 0% 0%; }
  to   { background-position: 3% -2%, -3% 2%, 2% -3%; }
}

@media (prefers-reduced-motion: reduce) {
  .forest-js .forest-canopy__photo.forest-canopy__layer--far,
  .forest-js .forest-canopy__layer--mid,
  .forest-js .forest-canopy__layer--near {
    animation: none;
  }
}

/* ==========================================================================
   Section heads — a numeral, a title, a long hairline (the dream pattern)
   ========================================================================== */

.forest-sec {
  display: flex;
  align-items: baseline;
  gap: 1.1rem;
  margin-bottom: clamp(1.6rem, 4vh, 2.8rem);
  max-width: 1160px;
  margin-inline: auto;
  padding-inline: clamp(20px, 5vw, 56px);
}
.forest-sec__no {
  flex: none;
  font-size: 0.82rem;
  letter-spacing: 0.24em;
  color: var(--forest-mid-press);
}
.forest-sec__title {
  font-weight: 500;
  font-size: clamp(1.7rem, 3.4vw, 2.4rem);
  line-height: 1.15;
  letter-spacing: -0.02em;
  color: var(--forest-ink);
}
.forest-sec__title:lang(ko) {
  letter-spacing: 0;
}
.forest-sec__ko {
  font-size: 0.62em;
  color: var(--forest-ink-soft);
  margin-left: 0.35em;
}
.forest-sec::after {
  content: "";
  flex: 1;
  align-self: center;
  height: 1px;
  background: var(--forest-hairline);
  margin-left: 0.6rem;
}

/* ==========================================================================
   Hero — the arrival beneath the canopy
   ========================================================================== */

.forest-hero {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding:
    clamp(80px, 18vh, 160px)
    clamp(20px, 5vw, 60px)
    clamp(48px, 10vh, 96px);
}

.forest-kicker {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.24em;
  color: var(--forest-mid-press);
  margin: 0 0 var(--forest-space-8);
}
.forest-kicker :lang(ko) {
  text-transform: none;
  letter-spacing: 0;
}

.forest-title {
  font-weight: 700;
  font-size: clamp(3.5rem, 12vw, 8rem);
  line-height: 0.9;
  letter-spacing: -0.03em;          /* display: tight tracking */
  margin: 0 0 var(--forest-space-6);
  text-wrap: balance;
}
.forest-title :lang(ko) {
  font-size: 0.4em;
  color: var(--forest-mid);
  display: block;
  margin-top: var(--forest-space-2);
  letter-spacing: 0;
}

.forest-sub {
  max-width: 540px;
  margin: 0;
  color: var(--forest-ink-soft);
  opacity: 0.85;
  font-size: clamp(0.95rem, 1.6vw, 1.1rem);
  line-height: 1.7;
  text-wrap: pretty;
}

.forest-hero__hint {
  margin-top: var(--forest-space-12);
  font-size: 0.82rem;
  letter-spacing: 0;
  color: var(--forest-mid-press);
  opacity: 0.7;
}

/* ==========================================================================
   하나 · The descent — a pinned canopy that dissolves toward the floor
   ========================================================================== */

.forest-descent {
  position: relative;
  z-index: 2;
  /* tall so there is scroll-room to scrub through the pinned scene */
  min-height: 220vh;
  background: var(--forest-light);
}

.forest-descent__inner {
  position: sticky;
  top: 0;
  min-height: 100vh;
  min-height: 100svh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  padding: clamp(40px, 8vh, 80px) clamp(20px, 5vw, 60px);
  /* the sky color lerps from light to deep in oklab as we descend */
  background: color-mix(
    in oklab,
    var(--forest-light) calc((1 - var(--forest-scrub, 0)) * 100%),
    var(--forest-deep)
  );
  /* text color lerps from ink (day) to light (floor) — contrast holds at both ends */
  color: color-mix(
    in oklab,
    var(--forest-ink) calc((1 - var(--forest-scrub, 0)) * 100%),
    var(--forest-light)
  );
  isolation: isolate;
}

.forest-descent__word {
  font-size: clamp(1.5rem, 4vw, 2.5rem);
  font-weight: 600;
  line-height: 1.25;
  margin: 0 0 var(--forest-space-4);
  letter-spacing: 0;
  opacity: calc(0.4 + var(--forest-scrub, 0) * 0.6);
}

.forest-descent__en {
  margin: var(--forest-space-6) 0 0;
  font-size: 0.95rem;
  opacity: calc(0.45 + var(--forest-scrub, 0) * 0.4);
  text-wrap: pretty;
}
.forest-descent__en em {
  font-style: italic;
  letter-spacing: 0.01em;
}

/* ==========================================================================
   둘 · The layers of the canopy — depth made legible
   ========================================================================== */

.forest-layers {
  position: relative;
  z-index: 2;
  max-width: 1160px;
  margin-inline: auto;
  padding:
    clamp(72px, 12vh, 150px)
    clamp(20px, 5vw, 56px)
    clamp(56px, 10vh, 120px);
}

.forest-layers__lede {
  max-width: 36rem;
  margin: 0 auto clamp(2rem, 5vh, 3.4rem);
  text-align: center;
}
.forest-layers__lede em {
  display: block;
  font-size: 1.25rem;
  line-height: 1.5;
  color: var(--forest-ink);
  margin-bottom: 0.4rem;
}
.forest-layers__lede span {
  display: block;
  color: var(--forest-ink-soft);
  font-size: 0.95rem;
}

.forest-layers__list {
  display: grid;
  gap: clamp(16px, 3vh, 28px);
  max-width: 40rem;
  margin-inline: auto;
}

/* each depth card carries a left edge that darkens with depth */
.forest-layers__item {
  display: grid;
  grid-template-columns: 4rem 1fr;
  align-items: baseline;
  gap: 0.4rem 1.1rem;
  padding: var(--forest-space-6) var(--forest-space-6) var(--forest-space-6) var(--forest-space-8);
  border-left: 3px solid var(--forest-mid);
  background: linear-gradient(90deg, rgba(220, 252, 231, 0.5) 0%, transparent 80%);
  border-radius: 0 12px 12px 0;
  box-shadow:
    0 1px 2px rgba(5, 46, 22, 0.04),
    0 6px 14px rgba(5, 46, 22, 0.05);
  transition:
    transform 240ms var(--forest-ease-spring),
    box-shadow 240ms var(--forest-ease-sway);
}
.forest-layers__item:hover {
  transform: translateX(4px);
  box-shadow:
    0 2px 4px rgba(5, 46, 22, 0.05),
    0 10px 22px rgba(5, 46, 22, 0.08);
}

.forest-layers__item--far {
  border-left-color: var(--forest-mid);
  opacity: 0.92;
}
.forest-layers__item--mid {
  border-left-color: var(--forest-mid-press);
}
.forest-layers__item--near {
  border-left-color: var(--forest-ink);
}

.forest-layers__no {
  font-size: 0.82rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--forest-mid-press);
  grid-row: span 2;
}

.forest-layers__name {
  font-size: clamp(1.1rem, 2vw, 1.3rem);
  font-weight: 600;
  letter-spacing: 0;
  color: var(--forest-ink);
}

.forest-layers__en {
  font-size: 0.92rem;
  line-height: 1.55;
  color: var(--forest-ink-soft);
  text-wrap: pretty;
}
.forest-layers__en em {
  font-style: italic;
  letter-spacing: 0.01em;
}

/* ==========================================================================
   셋 · The understory — ecosystem as quiet cards
   ========================================================================== */

.forest-floor {
  position: relative;
  z-index: 2;
  max-width: 1160px;
  margin-inline: auto;
  padding:
    0
    clamp(20px, 5vw, 56px)
    clamp(72px, 12vh, 140px);
}

.forest-floor__lede {
  max-width: 34rem;
  margin: 0 auto clamp(2rem, 5vh, 3.4rem);
  text-align: center;
}
.forest-floor__lede em {
  display: block;
  font-size: 1.25rem;
  line-height: 1.5;
  color: var(--forest-ink);
  margin-bottom: 0.4rem;
}
.forest-floor__lede span {
  display: block;
  color: var(--forest-ink-soft);
  font-size: 0.95rem;
}

.forest-floor__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: clamp(20px, 3vw, 32px);
  max-width: 980px;
  margin-inline: auto;
}

.forest-floor__card {
  position: relative;
  padding: var(--forest-space-8) var(--forest-space-6) var(--forest-space-6);
  border-radius: 18px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.7) 0%, rgba(220, 252, 231, 0.5) 100%);
  border: 1px solid var(--forest-hairline);
  backdrop-filter: blur(8px) saturate(140%);
  -webkit-backdrop-filter: blur(8px) saturate(140%);
  box-shadow:
    0 1px 2px  rgba(5, 46, 22, 0.04),   /* ambient */
    0 8px 18px rgba(5, 46, 22, 0.07),   /* key */
    0 24px 48px rgba(5, 46, 22, 0.05);  /* contact */
  transition:
    transform 280ms var(--forest-ease-spring),
    box-shadow 280ms var(--forest-ease-sway),
    border-color 200ms var(--forest-ease-sway);
}
.forest-floor__card::before {
  content: "";
  position: absolute;
  top: -1px;
  left: var(--forest-space-6);
  right: var(--forest-space-6);
  height: 3px;
  border-radius: 3px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    var(--forest-mid) 30%,
    var(--forest-mid-press) 70%,
    transparent 100%
  );
  opacity: 0.5;
  transition: opacity 280ms var(--forest-ease-sway);
}
.forest-floor__card:hover {
  transform: translateY(-4px);
  border-color: rgba(21, 128, 61, 0.32);
  box-shadow:
    0 2px 4px  rgba(5, 46, 22, 0.05),
    0 14px 28px rgba(5, 46, 22, 0.10),
    0 36px 64px rgba(5, 46, 22, 0.07);
}
.forest-floor__card:hover::before { opacity: 1; }
.forest-floor__card:focus-within {
  border-color: rgba(21, 128, 61, 0.36);
}

.forest-floor__h {
  font-size: 1.1rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  line-height: 1.3;
  margin: 0 0 var(--forest-space-3);
  color: var(--forest-ink);
}
.forest-floor__h :lang(ko) {
  color: var(--forest-mid-press);
  letter-spacing: 0;
}
.forest-floor__p {
  margin: 0;
  color: var(--forest-ink-soft);
  font-size: 0.95rem;
  line-height: 1.65;
  text-wrap: pretty;
}

/* ==========================================================================
   feTurbulence dappled light — the leaf overlay
   ========================================================================== */

.forest-dapple {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 3;
  pointer-events: none;
  mix-blend-mode: multiply;
  opacity: calc(0.5 - var(--forest-scrub, 0) * 0.3);  /* retreats as we descend */
}

/* ==========================================================================
   Footer — the deepest floor
   ========================================================================== */

.forest-foot {
  position: relative;
  z-index: 2;
  padding: clamp(48px, 10vh, 80px) clamp(20px, 5vw, 60px);
  text-align: center;
  background: var(--forest-floor-dark);
  color: var(--forest-light);
  font-size: 0.82rem;
  line-height: 1.7;
}
.forest-foot p { margin: 0 0 var(--forest-space-2); }

/* ==========================================================================
   Composition — responsive drifts at three breakpoints
   ========================================================================== */

@media (max-width: 900px) {
  .forest-layers__item {
    grid-template-columns: 3rem 1fr;
    gap: 0.3rem 0.9rem;
  }
  .forest-layers__no {
    grid-row: span 2;
    font-size: 0.74rem;
  }
  .forest-descent {
    min-height: 200vh;
  }
}

@media (max-width: 720px) {
  .forest-floor__card,
  .forest-layers__item {
    padding: var(--forest-space-6) var(--forest-space-4);
  }
  .forest-floor__card::before {
    left: var(--forest-space-4);
    right: var(--forest-space-4);
  }
  .forest-sec {
    gap: 0.8rem;
  }
}

@media (max-width: 480px) {
  .forest-kicker {
    font-size: 0.66rem;
    letter-spacing: 0.2em;
    margin-bottom: var(--forest-space-6);
  }
  .forest-layers__item:hover,
  .forest-floor__card:hover {
    transform: translateY(-2px);
  }
  .forest-layers__item:hover {
    transform: translateX(2px);
  }
}

/* ==========================================================================
   Reduced motion — the canopy, already still.
   The layers rest where composed (the --forest-px/--forest-py fallback is 0
   and the hook never runs), the descent shows its daylit composition
   (--forest-scrub fallback is 0), and the dapple holds one frame.
   ========================================================================== */

@media (prefers-reduced-motion: reduce) {
  .forest-canopy__photo.forest-canopy__layer--far,
  .forest-canopy__layer--mid,
  .forest-canopy__layer--near {
    transform: none;
  }
}
